/* ==============================================================
   Main Menu (Desktop & Mobile) - Hover & Active States
   ============================================================== */

/* Smooth transition for all links */
.theme-main-menu .menu-item > a,
#mobile-primary-menu .menu-item > a {
  transition: all 0.2s ease-in-out;
}

/* Hover State for all links */
.theme-main-menu .menu-item:hover > a,
.theme-main-menu .menu-item:hover > div > a, /* for custom dropdown toggles */
#mobile-primary-menu .menu-item:hover > a {
  color: var(--purple);
}

/* Optional: Slight background highlight for submenu items on hover */
.sub-menu .menu-item:hover > a {
  background-color: #f8fafc; /* Tailwind slate-50 */
}

/* 
   Active State: 
   Applies to the exact current page (.current-menu-item) 
   AND the parent dropdown if a sub-page is active (.current-menu-ancestor) 
*/
.theme-main-menu .current-menu-item > a,
.theme-main-menu .current-menu-ancestor > a,
.theme-main-menu .current-menu-ancestor > div > a,
#mobile-primary-menu .current-menu-item > a,
#mobile-primary-menu .current-menu-ancestor > a,
#mobile-primary-menu .current-menu-item > div,
#mobile-primary-menu .current-menu-ancestor > div {
  color: var(--purple);

}

.contact-form-card form input, .contact-form-card form textarea {
    background: var(--white);;
}

.innerpage-breadcrumb {
    justify-content: center;
}

/* =========================================
   COURSE RICH TEXT STYLING (About this Course)
   ========================================= */
.course-content {
  color: #4b5563; /* Gray-600 */
  line-height: 1.75;
  font-size: 1rem;
}

.course-content h2, 
.course-content h3 {
  font-family: var(--font-heading);
  color: #111827;
}

/* H2 (e.g. Tap Dance) */
.course-content h2 {
  font-size: 1.5rem;
  font-weight: 800;
  margin-top: 2.5rem;
  margin-bottom: 1rem;
  padding-bottom: 0.5rem;
  border-bottom: 2px solid #f3f4f6;
}

.course-content h2 strong {
  font-weight: 800;
}

/* H3 (e.g. Line Dance) */
.course-content h3 {
  font-weight: 700;
  color: var(--purple);
  margin-top: 2rem;
  margin-bottom: 1rem;
}

.course-content h2:first-child,
.course-content h3:first-child {
  margin-top: 0;
}

/* Lists and Bullet Points */
.course-content ul {
  list-style-type: none;
  padding-left: 0;
  margin-bottom: 2rem;
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.75rem;
}

@media (min-width: 640px) {
  .course-content ul {
    /* Puts the bullets in a nice 2-column grid on desktop! */
    grid-template-columns: repeat(2, 1fr);
    gap: 0.75rem 1.5rem;
  }
}

.course-content li {
  position: relative;
  background: #f9fafb;
  border-radius: 0.5rem;
  padding: 0.875rem 1rem 0.875rem 2.75rem;
  border: 1px solid #f3f4f6;
  transition: all 0.2s ease;
  display: flex;
  align-items: center;
}

/* Premium Hover Effect on List Items */
.course-content li:hover {
  background-color: var(--white);
  border-color: rgba(119, 61, 190, 0.3);
  box-shadow: 0 4px 12px rgba(119, 61, 190, 0.08);
  transform: translateX(4px);
}

/* Custom Purple Bullet Dot */
.course-content li::before {
  content: "•";
  position: absolute;
  left: 1.25rem;
  color: var(--purple);
  font-weight: 900;
  font-size: 1.5rem;
  line-height: 0;
}

/* Paragraph spacing */
.course-content p {
  margin-bottom: 1rem;
}

/* Prevents weird spacing if text is wrapped in <p> inside a <li> */
.course-content li p {
  margin: 0; 
  font-size: 0.95rem;
}

.course-content strong {
  color: #111827;
  font-weight: 700;
}

.section-about-course h2 {
    border-bottom: 1px solid #eee;
    padding-bottom: 15px;
    margin-bottom: 20px;
}
.section-ready-get-started p {
    margin: 0 auto 20px auto;
}
.section-about-course {
    margin-top: 40px;
background: #fff;
}
/* =========================================
   SHOP COMPONENT STYLING
   ========================================= */
.shop-toolbar {
  border-bottom: 1px solid #f3f4f6;
}

.shop-filter-group {
  background-color: rgba(249, 250, 251, 0.8);
  padding: 0.375rem;
  border-radius: 0.75rem;
  box-shadow: inset 0 2px 4px 0 rgba(0, 0, 0, 0.06);
  border: 1px solid #f3f4f6;
}

.shop-filter-btn {
  padding-top: 0.75rem;
  padding-bottom: 0.75rem;
  border-radius: 0.5rem;
  font-size: 0.875rem;
  font-weight: 700;
  transition: all 0.2s ease;
  color: #6b7280;
}
@media (min-width: 768px) { .shop-filter-btn { padding-left: 2rem; padding-right: 2rem; } }

.shop-filter-btn:hover { color: #111827; }
.shop-filter-btn.active {
  background-color: var(--white);
  color: var(--purple);
  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}

.shop-title {
  font-family: var(--font-heading);
  font-size: 1.875rem;
  font-weight: 800;
  color: #111827;
}

.shop-search-icon {
  left: 1rem;
  color: #9ca3af;
}

.shop-search-input {padding: 0.875rem 1rem 0.875rem 3rem;background-color: #f9fafb;border: 1px solid #e5e7eb;border-radius: 0.75rem;font-size: 0.875rem;font-weight: 500;transition: all 0.2s ease;color: #111827;}
.shop-search-input::placeholder { color: #9ca3af; }
.shop-search-input:focus {outline: none;border-color: var(--purple);box-shadow: 0 0 0 4px rgba(119, 61, 190, 0.1);}

/* Card UI */
.shop-card {background-color: var(--white);border-radius: 1.5rem;overflow: hidden;border: 1px solid #f3f4f6;box-shadow: 0 10px 40px rgba(0, 0, 0, 0.04);transition: all 0.3s ease;}

.shop-card:hover {border-color: rgba(119, 61, 190, 0.3);transform: translateY(-4px);box-shadow: 0 16px 50px rgba(119, 61, 190, 0.08);}

.shop-card-img-wrap {aspect-ratio: 4 / 3;background-color: #f9fafb;overflow: hidden;}

.shop-card-img {transition: transform 0.7s cubic-bezier(0, 0, 0.2, 1);}

.shop-card:hover .shop-card-img { transform: scale(1.05); }

.shop-placeholder-icon { color: #d1d5db; }

.shop-card-badge-wrap {top: 1rem; left: 1rem;}

.shop-card-badge {padding: 0.375rem 1rem;border-radius: 9999px;font-size: 11px;font-weight: 700;letter-spacing: 0.05em;text-transform: uppercase;backdrop-filter: blur(12px);box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);color: var(--white);}

.shop-card-badge.course-badge { background-color: rgba(119, 61, 190, 0.9); }
.shop-card-badge.product-badge { background-color: rgba(224, 23, 131, 0.9); }

.shop-card-overlay {background: linear-gradient(to top, rgba(0, 0, 0, 0.2), transparent);opacity: 0;transition: opacity 0.3s ease;}

.shop-card:hover .shop-card-overlay { opacity: 1; }

.shop-card-content {padding: 1.5rem; background-color: var(--white);}
@media (min-width: 768px) { .shop-card-content { padding: 2rem; } }

.shop-card-title {font-size: 1.25rem;font-weight: 700;color: #111827;margin-bottom: 0.75rem;font-family: var(--font-heading);line-height: 1.25;transition: color 0.2s ease;display: -webkit-box;-webkit-line-clamp: 2;-webkit-box-orient: vertical;overflow: hidden;
}

.shop-card:hover .shop-card-title { color: var(--purple); }

.shop-card-footer {padding-top: 1.5rem;border-top: 1px solid #f9fafb;}

.shop-card-price-sale { font-size: 1.25rem; font-weight: 800; color: var(--purple); }
.shop-card-price-original { font-size: 0.875rem; font-weight: 500; color: #9ca3af; text-decoration: line-through; }
.shop-card-price-regular { font-size: 1.25rem; font-weight: 800; color: #111827; }
.shop-card-details-link { font-size: 0.875rem; font-weight: 700; color: var(--purple); }

.shop-card-arrow {color: #9ca3af;background-color: #f9fafb;width: 2.5rem;height: 2.5rem;border-radius: 9999px;transition: all 0.3s ease;}

.shop-card:hover .shop-card-arrow {background-color: var(--purple);color: var(--white);box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);transform: translateX(4px);
}

/* Empty State */
.shop-empty-state { padding: 8rem 1rem; background-color: #f9fafb; border-radius: 1.5rem; border: 1px dashed #f3f4f6; }
.shop-empty-icon { color: #d1d5db; margin-bottom: 1.5rem; }
.shop-empty-title { font-size: 1.5rem; font-weight: 700; color: #111827; margin-bottom: 0.75rem; font-family: var(--font-heading); }
.shop-empty-desc { color: #6b7280; max-width: 28rem; }
.shop-empty-btn { margin-top: 2rem; padding: 0.75rem 1.5rem; background-color: var(--white); border: 1px solid #e5e7eb; color: #374151; border-radius: 0.75rem; font-weight: 700; box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05); transition: all 0.2s ease; }
.shop-empty-btn:hover { background-color: #f9fafb; color: var(--purple); }

/* Blog Sidebar */
.blog-sidebar h3 {font-family: var(--font-heading);font-size: 20px !important;color: var(--heading);margin-bottom: 20px;}
.blog-sidebar-widget {background-color: var(--white);border-radius: var(--radius);padding: 32px;border: 1px solid #f0f0f0;position: relative;overflow: hidden;/* Identical Normal Shadow */box-shadow: 0 10px 40px rgba(0, 0, 0, 0.04);transition: box-shadow 0.3s ease, transform 0.3s ease;}
.blog-sidebar-widget:hover {box-shadow: 0 16px 50px rgba(119, 61, 190, 0.08);  transform: translateY(-2px);}
.blog-sidebar-widget::before {content: "";position: absolute;top: 0;left: 0;width: 100%;height: 4px;background: linear-gradient(90deg, var(--blue), var(--pink), var(--purple));opacity: 0.8;}
.blog-sidebar-title {font-family: var(--font-heading);font-size: 22px !important;line-height: 1.4;font-weight: 700;color: var(--heading);margin-bottom: 24px;position: relative;display: inline-block;}
.blog-search-form {position: relative;width: 100%;}
.blog-search-input {width: 100%;padding: 16px 48px 16px 20px;background-color: #f8f9fa;border: 2px solid transparent;border-radius: var(--radius);color: var(--body);font-family: var(--font-body);font-size: 16px;transition: all 0.3s ease;outline: none;box-sizing: border-box;}
.blog-search-input:focus {background-color: var(--white);border-color: rgba(119, 61, 190, 0.3);box-shadow: 0 0 0 4px rgba(119, 61, 190, 0.1);}
.blog-search-input::placeholder {color: #a0aab5;}
.blog-search-btn {position: absolute;right: 16px;top: 50%;transform: translateY(-50%);background: transparent;border: none;color: #a0aab5;cursor: pointer;transition: color 0.3s ease, transform 0.3s ease;padding: 0;display: flex;align-items: center;justify-content: center;}
.blog-search-input:focus + .blog-search-btn,
.blog-search-btn:hover {color: var(--purple); transform: translateY(-50%) scale(1.1);}
.recent-posts-list {display: flex;flex-direction: column;gap: 12px;}
.recent-post-item {display: block;padding: 5px 0px;transition: all 0.3s ease;text-decoration: none;}
.recent-post-item:hover {transform: translateX(6px);}
.recent-post-title {color: var(--heading);font-size: 16px;font-weight: 600;line-height: 1.4;margin-bottom: 8px;transition: color 0.2s ease;display: -webkit-box;-webkit-line-clamp: 2;-webkit-box-orient: vertical;overflow: hidden;}
.recent-post-item:hover .recent-post-title {color: var(--pink);}
.recent-post-date {color: #888;font-size: 13px;display: flex;align-items: center;gap: 6px;}
.recent-post-date::before {content: "";display: inline-block;width: 14px;height: 14px;background: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23888" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg>') no-repeat center; background-size: contain;}

/* Blog Post Card */
.blog-post-card {background-color: var(--white);border-radius: var(--radius);border: 1px solid #f0f0f0;display: flex;flex-direction: row;overflow: hidden;/* Identical Normal Shadow */box-shadow: 0 10px 40px rgba(0, 0, 0, 0.04);transition: box-shadow 0.3s ease, transform 0.3s ease;}
.blog-post-card:hover {  box-shadow: 0 16px 50px rgba(119, 61, 190, 0.08);
  transform: translateY(-2px);}
.blog-post-img-wrap {display: block;width: 30%;position: relative;overflow: hidden;flex-shrink: 0;}
.blog-post-img {width: 100%;height: 100%;object-fit: cover;position: absolute;inset: 0;transition: transform 0.7s ease;}
.blog-post-card:hover .blog-post-img {transform: scale(1.05);}
.blog-post-img-spacer {display: none;}
.blog-post-content {flex: 1;min-width: 0;padding: 32px;display: flex;flex-direction: column;justify-content: center;}
.blog-post-category {display: flex;flex-wrap: wrap;align-items: center;gap: 8px;font-size: 14px;color: var(--purple);font-weight: 600;margin-bottom: 8px;}
.blog-post-category a:hover {text-decoration: underline;}
.blog-post-title {color: var(--heading);font-family: var(--font-heading);font-size: clamp(20px, 2.5vw, 24px) !important;font-weight: 600;line-height: 1.3;margin-bottom: 12px;transition: color 0.2s ease;}
.blog-post-card:hover .blog-post-title {color: var(--purple);}
.blog-post-meta {display: flex;align-items: center;gap: 12px;font-size: 14px;color: #6b7280;margin-bottom: 16px;font-weight: 500;}
.blog-post-excerpt {color: var(--body);font-size: 16px;line-height: 1.75;}
.blog-post-read-more {color: var(--purple);font-weight: 500;margin-top: 12px;display: inline-flex;align-items: center;gap: 4px;}
.blog-post-read-more:hover {text-decoration: underline;}
.blog-post-img {width: 100%;height: 100%;object-fit: cover;position: absolute;inset: 0;transition: transform 0.7s ease; /* Slow, smooth zoom transition */
}
.blog-post-card:hover .blog-post-img {transform: scale(1.05); /* Zooms in 5% on hover */}


/* IMPORT FONT */
/*@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Plus+Jakarta+Sans:wght@600&family=Poppins:wght@500&display=swap");*/

:root{--white:#fff;--black:#111;--body:#474747;--heading:#1c1c1c;--pink:#e01783;--blue:#00758d;--purple:#773dbe;--dark:#161a29;--light:#f6f6f6;--font-body:Inter;--font-heading:"Plus Jakarta";--container:1200px;--radius:12px;}

h1, h2, h3{font-family:var(--font-heading);color:var(--heading);margin:0;}
h1{font-size:clamp(30px, 4vw, 55px)!important;line-height:1.16;font-weight:500;}
h2{font-size:clamp(24px, 3vw, 40px)!important;line-height:1.25;font-weight:500;}
h3{font-size:24px!important;line-height:1.65;font-weight:600;}
.section-dark h1, .section-dark h2, .section-dark h3{color:var(--white);}

/* COMMON CSS USED ON ALL PAGES */
*{box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{margin:0;color:var(--body);font:400 16px/1.75 var(--font-body);background:var(--white);}
img{display:block;}
a{text-decoration:none;}
button{font:inherit;}
.container {
    box-sizing: border-box;
    width: 100% !important;
    max-width: 1200px !important;
    margin-right: auto !important;
    margin-left: auto !important;
    padding-right: 15px !important;
    padding-left: 15px !important;
}
.section-padding{padding:80px 0;}
.row-align-center{align-items:center;}
.row-align-start{align-items:flex-start;}
.bg-white,.section-white{background:var(--white);}
.bg-light,.section-light{background:var(--light);}
.section-dark{background:var(--dark);color:var(--white);overflow:hidden;position:relative;}
.section-dark:before, .section-dark:after{content:"";position:absolute;border-radius:50%;filter:blur(50px);pointer-events:none;}
.section-dark:before{width:400px;height:400px;background:rgba(119, 61, 190, .12);left:-70px;top:-70px;}
.section-dark:after{width:600px;height:600px;background:rgba(224, 23, 131, .12);right:2%;top:0;}
.section-dark>.container{position:relative;z-index:1;}
.txt-pink{color:var(--pink);}
.title-break{display:block;}
p{margin:0;}
.eyebrow{font-size:18px;line-height:1.5;font-weight:500;margin-bottom:12px;}
.theme-btn{display:inline-flex;align-items:center;justify-content:flex-end;gap:12px;padding:7px 7px 7px 20px;border-radius:var(--radius);color:#fff;font-weight:500;line-height:1.2;}
.section-heading{margin-bottom:38px;}

/* Reusable heading strokes: add class="stroke-title" to the heading. */
.stroke-title::after{content:"";display:block;width:155px;height:18px;margin-top:2px;background:url("https://ipdav.com/newweb-new/uploads/2026/08/blue-stroke-line.png") center/contain no-repeat;pointer-events:none;}
.stroke-title.stroke-wide::after{width:225px;}
.stroke-title.stroke-short::after{width:89px;height:16px;}
.stroke-title.stroke-pink::after{background-image:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785927006/custom-cms/pink-stroke-line.png");}
.section-heading-center{display:flex;flex-direction:column;align-items:center;text-align:center;}
.section-heading-center .stroke-title::after{margin-left:auto;margin-right:auto;}
.section-heading.left .stroke-title::after{width:135px;margin-left:240px;}
.trust-strip{background:var(--blue);color:#fff;padding:40px 0;position:relative;overflow:hidden;}
.trust-strip::after{content:"";position:absolute;width:115px;height:94px;right:0;top:50%;transform:translateY(-50%);background:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785916237/custom-cms/trust-strip-flower.png") center/contain no-repeat;opacity:.08;pointer-events:none;}
.trust-strip .container{position:relative;z-index:1;}
.trust-item{display:flex;align-items:center;gap:15px;font-size:20px;line-height:1.4;}
.decorative-right{position:relative;overflow:hidden;}
.decorative-right:after, .decorative-right-top:after{content:"";position:absolute;width:415px;height:415px;background:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785916241/custom-cms/yoga-girl-background.png") center/contain no-repeat;right:0;bottom:0;pointer-events:none;}
.decorative-left{position:relative;overflow:hidden;}
.decorative-left:before{content:"";position:absolute;width:400px;height:414px;left:0;top:0;background:url("https://ipdav.com/newweb-new/uploads/2026/08/hosting-event-background.png") center/contain no-repeat;}
.check-list{list-style:none;margin:0 0 32px;padding:0;display: flex; flex-direction: column; gap:20px;}
.devices{position:relative;}
.devices .laptop{width:692px;margin-left:auto;}
.devices .phone{position:absolute;left:0;bottom:0;width:158px;z-index:2;}
.page-banner{padding:80px 0;display:grid;place-items:center;text-align:center;isolation:isolate;}
.page-banner .container{position:relative;z-index:2;}
.page-banner-art{position:absolute;z-index:0;width:614px;height:400px;left:50%;top:50%;transform:translate(-50%, -50%);object-fit:contain;opacity:.34;pointer-events:none;}
.page-banner h1{font-size:clamp(42px, 4vw, 55px)!important;}
.page-banner p{line-height:2;}
.gradient-divider{display:block;width:200px;height:2px;margin:28px auto 20px;border-radius:100px;background:linear-gradient(90deg, var(--blue) 0%, var(--pink) 50%, var(--purple) 100%);}
.section-heading-left{margin-bottom:28px;text-align:left;}
.section-heading-left h2{display:block;}
.section-heading-left .stroke-title::after{margin-left:0;}
.contact-heading .stroke-title::after{width:108px;height:15px;margin-left:96px;}
.on-demand-intro-heading .stroke-title::after{width:151px;height:20px;margin-left:0;}
.class-types-copy .stroke-title::after{width:222px;}
.studio-heading .stroke-title::after{width:146px;height:16px;margin-left:76px;}
.puppets-stroke-title::after{width:222px;height:16px;}
.emily-heading .stroke-title::after{margin-left:calc(50% + 145px);transform:translateX(-50%);}
.training-modules-heading .stroke-title::after{margin-left:185px;}
.training-details-copy .stroke-title.stroke-wide::after{width:225px;height:20px;}
.training-faq-heading .stroke-title::after{width:223px;}
.team-section .stroke-title::after{margin-left:auto;margin-right:auto;}
.content-split{position:relative;overflow:hidden;}
.content-split > .container, .decorative-left > .container, .pattern-right > .container{position:relative;z-index:1;}
.content-copy > p{line-height:2;}
.content-copy .theme-btn{margin-top:32px;}
.content-media{overflow:hidden;border-radius:var(--radius);}
.content-media img{width:100%;object-fit:cover;}
.content-media-wide img{height:370px;}
.content-figure{margin:0;}
.content-figure img{width:100%;height:251px;border-radius:var(--radius);object-fit:cover;}
.content-figure figcaption{margin-top:20px;color:var(--heading);font-size:20px;line-height:1.6;font-weight:500;}
.pattern-right{position:relative;overflow:hidden;}
.pattern-right::after{content:"";position:absolute;width:400px;height:414px;right:0;top:0;background:url("https://ipdav.com/newweb-new/uploads/2026/08/hosting-event-background.png") center/contain no-repeat;pointer-events:none;}
.feature-cta{padding:20px;border:1px solid var(--pink);border-radius:20px;display:flex;align-items:center;justify-content:space-between;gap:16px;}
.feature-cta-copy{display:flex;align-items:center;gap:20px;}
.feature-cta-copy > img{margin: 0;}
.inner-hero-title{font-family:"Plus Jakarta";line-height:1.5;font-weight:500; margin-bottom: 15px;}
.inner-hero-title-accent{color:#E81A7B;}
.inner-hero-subtitle{font-family:"Inter", sans-serif;font-size:16px;line-height:32px;font-weight:400;color:var(--white);}
.inner-page-hero-bg{background-size:contain;background-position:center;background-repeat:no-repeat;background-color:#161a29;}
.about-banner{min-height:320px;padding:80px 0;background:#161a29!important;position:relative;overflow:hidden;isolation:isolate;}
.about-banner::before{width:214px;height:214px;left:-25px;top:69px;background:rgba(224,23,131,.12);filter:blur(50px);transform:scaleY(-1);}
.about-banner::after{width:209px;height:209px;left:auto;right:-27px;top:69px;background:rgba(119,61,190,.12);filter:blur(50px);}
