.studio-address{display:flex;align-items:center;justify-content:flex-end;gap:12px;color:#333;font-size:20px;line-height:1.6;font-weight:500;text-align:right;}
.studio-address img{width:24px;height:24px;flex:0 0 auto;}
.studio-map-btn{justify-content:space-between;}
.studio-pricing-list{display:grid;gap:20px;}
.studio-price-row{padding:20px 40px 20px 24px;display:grid;grid-template-columns:minmax(0, 1fr) 1px 326px;align-items:center;gap:40px;border-radius:var(--radius);background:var(--white);box-shadow:0 4px 12px rgba(0, 0, 0, .12);}
.studio-class-name{display:flex;align-items:center;gap:13px;color:#333;font-size:20px;line-height:1.6;font-weight:500;}
.studio-class-name img{width:50px;height:50px;flex:0 0 auto;}
.studio-price-divider{width:1px;height:60px;border-radius:100px;background:linear-gradient(180deg, var(--blue) 0%, var(--pink) 50%, var(--purple) 100%);}
.studio-price{color:#333;line-height:1.5;}
.studio-price strong{font-weight:600;}
.studio-price-pink strong{color:var(--pink);}
.studio-price-blue strong{color:var(--blue);}
.studio-price-purple strong{color:var(--purple);}
.studio-calendar{margin:80px 0 0 !important;width:100%;overflow:hidden;border:1px solid #999;background:#eef3f9;}
.studio-calendar img{width:100%;height:auto;}
.puppets-banner .page-banner-art{width:614px;height:400px;opacity:.72;object-fit:contain;}
.puppets-intro{position:relative;overflow:hidden;}
.puppets-intro::before, .puppets-intro::after{content:"";position:absolute;pointer-events:none;background-position:center;background-repeat:no-repeat;background-size:contain;}
.puppets-intro::before{width:132px;height:142px;left:0;top:0;background-image:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785933144/custom-cms/puppets-arts-background-img.png");}
.puppets-intro::after{width:200px;height:200px;right:0;bottom:0;background-image:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785933108/custom-cms/blue-face-background-img.png");}
.puppets-intro > .container{position:relative;z-index:1;}
.puppets-intro-heading{margin-bottom:14px;}
.puppets-intro-copy > p{color:#3a3a3a;line-height:2;}
.puppets-intro-image{margin:32px 0 0 !important;overflow:hidden;border-radius:var(--radius);}
.puppets-intro-image img{width:100%;height:370px;object-fit:cover;}
.puppet-benefit-list{display:grid;gap:10px;}
.puppet-benefit-card{padding:20px;display:grid;grid-template-columns:46px 1fr;align-items:start;gap:20px;border-radius:var(--radius);background:#f5f5f5;}
.puppet-benefit-card > img{width:46px;height:46px;}
.puppet-benefit-card h3{color:#333;font-family:var(--font-body);font-size:20px!important;line-height:1.6;font-weight:500;}
.puppet-benefit-card p{color:#3a3a3a;line-height:1.875;}
.emily-heading{margin:0 auto 56px;text-align:center;}
.emily-heading .section-heading{margin-bottom:0;}
.emily-heading h3{margin:4px 0 22px;color:var(--heading);}
.emily-heading p{line-height:1.875;}
.emily-feature, .emily-poster{margin:0;}
.emily-feature img, .emily-poster img{width:100%;height:302px;object-fit:cover;}
.emily-feature figcaption, .emily-poster figcaption{margin-top:18px;color:var(--body);line-height:1.5;text-align:center;}
.emily-poster figcaption{text-align:left;}
.character-section{position:relative;overflow:hidden;}
.character-section::before{content:"";position:absolute;width: 179px;height: 179px;left:-6px;top: 0;background:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785933135/custom-cms/paint-palate-background-img.png") center/contain no-repeat;opacity:.78;pointer-events:none;z-index:0;}
.character-section > .container{position:relative;z-index:1;}
.character-card{height:100%;overflow:hidden;border-radius:var(--radius);background:#f5f5f5;}
.character-card > img{width:100%;height:340px;object-fit:cover;margin:0;}
.character-card-copy{padding:20px;}
.character-card-copy h2{font-size:32px!important;line-height:1.25;}
.character-card-copy h3{margin-top:6px;color:var(--heading);font-size:24px!important;font-weight:500;}
.character-card-copy p{margin-top:18px;line-height:1.5;}
.performance-section::after{background-image:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785916220/custom-cms/hosting-event-background.png");}
.puppet-video-card{margin:0;overflow:hidden;border-radius:var(--radius);}
.puppet-video-card iframe{display:block;width:100%;aspect-ratio:16/9;border:0;}
.performance-copy p{color:var(--heading);line-height:1.75;}
.performance-copy .theme-btn{margin-top:30px;}
.performance-card-grid{margin-top:60px;}
.performance-info-card{height:100%;padding:20px 32px;border-radius:var(--radius);background:var(--white);}
.performance-info-head{display:flex;align-items:center;gap:20px;margin-bottom:18px;}
.performance-info-head img{width:50px;height:50px;margin:0;}
.performance-info-head h3{color:var(--heading);font-family:var(--font-body);font-size:20px!important;line-height:1.6;font-weight:500;}
.performance-info-card p{color:var(--heading);line-height:1.75;}
.custom-puppet::after{width:210px;height:414px;right:0;top:0;border-radius:0;filter:none;background:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785933114/custom-cms/custom-puppet-construction-background-img.png") right center/contain no-repeat;}
.custom-puppet-copy h2{margin-bottom:26px;}
.custom-puppet-copy p{color:var(--white);line-height:2;}
.custom-puppet-copy .theme-btn{margin-top:32px;}
.pilates-performers{position:relative;overflow:hidden;}
.pilates-performers::before{content:"";position:absolute;width:179px;height:179px;right:0;bottom:0;background:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785933135/custom-cms/paint-palate-background-img.png") center/contain no-repeat;pointer-events:none;}
.pilates-performers > .container{position:relative;z-index:1;}
.pilates-performers-copy p{color:#3a3a3a;line-height:2;}
.pilates-video-card{margin:0;}
.pilates-video-card iframe{display:block;width:100%;max-width:100%;aspect-ratio:16/9;height:auto;border:0;}
.pilates-video-card figcaption{margin-top:10px;color:#3a3a3a;font-weight:600;line-height:2;}
.puppet-gallery{position:relative;overflow:hidden;}
.puppet-gallery::before, .puppet-gallery::after{content:"";position:absolute;width:279px;height:120px;bottom:0;pointer-events:none;}
.puppet-gallery::before{left:0;background:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785933137/custom-cms/pink-left-smoke-background.png") left bottom/contain no-repeat;}
.puppet-gallery::after{right:0;background:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785933138/custom-cms/pink-right-smoke-background.png") right bottom/contain no-repeat;}
.puppet-gallery > .container{position:relative;z-index:1;}
.puppet-gallery-grid img{width:100%;aspect-ratio:1;border-radius:var(--radius);object-fit:cover;}
.puppet-contact-copy h3{color:var(--white);font-family:var(--font-heading);font-size:24px!important;font-weight:500;}
.puppet-contact-copy h3 a{color:var(--pink);}
.puppet-contact-copy p{margin-top:12px;color:var(--white);line-height:2;}
.puppet-contact-copy .theme-btn{margin-top:30px;}
.puppet-contact-images img{width:100%;height:200px;border-radius:var(--radius);object-fit:cover;}
.puppet-program-card, .large-puppet-card, .johnny-card{border-radius:var(--radius);background:#f5f5f5;}
.puppet-program-card,.large-puppet-card{height:100%;}
.puppet-program-card{padding:32px 20px;}
.puppet-program-card h2{font-size:32px!important;line-height:1.25;}
.puppet-program-card h3{color:var(--heading);font-family:Plus Jakarta, var(--font-body);font-size:24px!important;font-weight:500;}
.puppet-program-card > p{margin-top:22px;}
.puppet-program-card > img, .program-image-stack{margin-top:50px;}
.puppet-program-card > img, .program-image-stack img{width:100%;border-radius:var(--radius);object-fit:cover;}
.puppet-program-card > img{height:476px;}
.program-image-stack{display:grid;gap:20px;}
.program-image-stack iframe{display:block;width:100%;aspect-ratio:16/9;border:0;border-radius:var(--radius);}
.program-image-stack img{height:300px;}
.large-puppet-card{padding:32px 20px;display:flex;flex-direction:column;gap:40px;background:var(--white);}
.large-puppet-card h2{font-size:32px!important;line-height:1.25;}
.large-puppet-card p{margin-top:18px;line-height:1.25;}
.large-puppet-card > img{width:100%;height:400px;margin-top:auto;border-radius:var(--radius);object-fit:cover;}
.johnny-card{padding:32px 20px;}
.johnny-card h2{margin-bottom:48px;font-size:32px!important;line-height:1.25;}
.johnny-card img{width:100%;height:384px;border-radius:var(--radius);object-fit:cover;}
.my-6 {margin-top: 0; margin-bottom: 0;}
.theme-btn-blue:hover {background: #E01783;}

/* Remove margin of image */
.prose :where(img):not(:where([class~="not-prose"], [class~="not-prose"] *)),
.prose :where(video):not(:where([class~="not-prose"], [class~="not-prose"] *)){margin-top:0; margin-bottom:0;}
.prose :where(figure):not(:where([class~="not-prose"], [class~="not-prose"] *)){margin-top:0; margin-bottom:0;}

/* Header */
.site-header{height:80px;position:sticky;top:0;z-index:50;background:var(--white)}
.logo-img{width:200px;height:58px;object-fit:contain}
.main-menu{font-size:16px;line-height:19px;color:#111}
.mb-8 {margin-bottom: 0;}

/* Footer */
.site-footer {padding: 80px 0 24px; background-color: #161A29; background-repeat: no-repeat; background-size: auto, auto, 96px 190px; background-position: right 0 bottom 56px; background-image: url(https://res.cloudinary.com/cgibjxmm/image/upload/v1786002616/custom-cms/footer-fitness-art-face.png);}
.footer-grid{align-items:start}
.footer-brand-col,.footer-links-col,.footer-services-col,.footer-cta-col{min-width:0}.footer-logo{width:285px;max-width:100%;margin-bottom:16px}
.footer-text{margin:0 0 20px;font-size:16px;line-height:24px;color:var(--white)}
.footer-heading{margin:0 0 24px;font-size:20px;line-height:24px;font-weight:600;color:var(--white)}
.footer-list{margin:0;padding:0;list-style:none}
.footer-list li{margin-bottom:20px;font-size:16px;line-height:19px;color:var(--white)}
.footer-title{margin:0 0 20px;font-family:'Plus Jakarta';font-size:40px;line-height:50px;font-weight:600;color:var(--white)}.footer-cta-text{max-width:387px;margin-bottom:24px}
.social-icon{width:40px;height:40px;border-radius:12px;background:var(--primary);display:flex;align-items:center;justify-content:center}.social-icon img{width:40px;height:40px;object-fit:contain}
.footer-line{height:1px;margin:60px 0 18px;border-radius:100px;background:#808080}
.copyright{margin:0;text-align:center;font-size:12px;line-height:15px;color:#B3B3B3}
.txt-accent {color: var(--pink);}
.footer-list a:hover {color: #E01783;}

